'use client';
import { useState, useEffect } from 'react';

export default function ScreenDetector({ onStreamStart, onStreamStop, isActive }) {
  const [fps, setFps] = useState(0);
  const [uptime, setUptime] = useState(0);
  const [logs, setLogs] = useState([
    { id: 1, t: 'ok',   m: 'Neural engine ready' },
    { id: 2, t: 'ok',   m: 'YOLO-v8 model loaded' },
    { id: 3, t: 'warn', m: 'Awaiting screen input' },
  ]);

  useEffect(() => {
    let iv;
    if (isActive) {
      iv = setInterval(() => {
        setUptime(p => p + 1);
        setFps(Math.floor(Math.random() * 6) + 26);
      }, 1000);
    } else {
      setUptime(0); setFps(0);
    }
    return () => clearInterval(iv);
  }, [isActive]);

  const addLog = (m, t = 'ok') =>
    setLogs(p => [...p.slice(-7), { id: Date.now(), t, m }]);

  const handleStart = async () => {
    try {
      addLog('Requesting display capture…', 'warn');
      const stream = await navigator.mediaDevices.getDisplayMedia({ video: { frameRate: 30 }, audio: false });
      addLog('Display capture granted', 'ok');
      addLog('Detection pipeline active', 'ok');
      onStreamStart(stream);
    } catch (e) {
      addLog(`Capture failed: ${e.message}`, 'err');
    }
  };

  const fmt = s => `${Math.floor(s/60).toString().padStart(2,'0')}:${(s%60).toString().padStart(2,'0')}`;

  return (
    <div className="card" style={{ height: '100%' }}>
      <div className="card-head">
        <span className="card-title">Screen Detector</span>
        <span className={`chip ${isActive ? 'chip-g' : 'chip-n'}`}>
          <span style={{ width: 5, height: 5, borderRadius: '50%', background: 'currentColor', display: 'inline-block' }} />
          {isActive ? 'LIVE' : 'IDLE'}
        </span>
      </div>

      <div className="card-body flex-col gap-12">
        {/* AI Status */}
        <div className="ai-block">
          <div className="ai-block-head">
            <span className="ai-block-lbl">AI Engine</span>
            <span className="ai-status-val" style={{ color: isActive ? 'var(--acc)' : 'var(--t3)' }}>
              <div className={`pulse-dot${isActive ? '' : ' red'}`} style={{ width: 5, height: 5 }} />
              {isActive ? 'ONLINE' : 'STANDBY'}
            </span>
          </div>
          {isActive && <div className="ai-bar"><div className="ai-bar-fill" /></div>}
        </div>

        {/* Meta rows */}
        <div className="flex-col gap-8">
          {[
            { k: 'status',  v: isActive ? 'detecting' : 'stopped', col: isActive ? 'var(--acc)' : 'var(--t3)' },
            { k: 'fps',     v: isActive ? `${fps} fps` : '—' },
            { k: 'uptime',  v: isActive ? fmt(uptime) : '00:00' },
            { k: 'model',   v: 'YOLO-v8-nano', col: 'var(--blu)' },
          ].map(r => (
            <div className="meta-row" key={r.k}>
              <span className="meta-k">{r.k}</span>
              <span className="meta-v" style={r.col ? { color: r.col } : {}}>{r.v}</span>
            </div>
          ))}
        </div>

        {/* Buttons */}
        <div className="flex-col gap-8">
          <button className="btn-start" onClick={handleStart} disabled={isActive}>
            <svg width="12" height="12" viewBox="0 0 12 12" fill="currentColor">
              <path d="M3 2l7 4-7 4V2z"/>
            </svg>
            Start Screen Detection
          </button>
          <button className="btn-stop" onClick={onStreamStop} disabled={!isActive}>
            <svg width="10" height="10" viewBox="0 0 10 10" fill="currentColor">
              <rect width="10" height="10" rx="2"/>
            </svg>
            Stop Detection
          </button>
        </div>

        {/* Log */}
        <div>
          <div className="sec-label">System Log</div>
          <div className="log-pane">
            {logs.map(l => (
              <div key={l.id} className={`log-line ${l.t}`}>
                <span style={{ opacity: .4, marginRight: 6 }}>›</span>{l.m}
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}
